{"code": "import math

def haversine(lat1, lon1, lat2, lon2, R=6371.0088):
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2-lat1)
    dl = math.radians(lon2-lon1)
    a = math.sin(dphi/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2*R*math.asin(math.sqrt(a))

# Googleplex, Mountain View, CA (Google HQ)
google = (37.422, -122.084)

# Candidate coordinates for Port of Brisbane (main container port of Queensland)
candidates = {
    "Wikipedia Port of Brisbane (-27.3802, 153.1802)": (-27.3802, 153.1802),
    "Fisherman Is. container terminal approx (-27.428, 153.196)": (-27.428, 153.196),
    "Common port DB Brisbane (-27.47, 153.13)": (-27.47, 153.13),
}

for name, coord in candidates.items():
    d = haversine(coord[0], coord[1], google[0], google[1])
    print(f"{name}: {d:.1f} km  -> rounded {round(d)} km")"}

